import {
  SidebarInset,
  SidebarProvider,
  SidebarTrigger,
} from "@/components/ui/sidebar";
import { Layout } from "@/features/page/layout";
import type { PropsWithChildren } from "react";
import { PatientMobileNav } from "./patient-mobile-nav";
import { PatientSidebar } from "./patient-sidebar";

export async function PatientNavigation({ children }: PropsWithChildren) {
  return (
    <SidebarProvider>
      <PatientSidebar />
      <SidebarInset className="bg-[var(--sidebar-patient)]">
        <header className="flex h-16 shrink-0 items-center gap-2">
          <Layout size="lg" className="flex items-center gap-2">
            <SidebarTrigger className="-ml-1" />
          </Layout>
        </header>
        <div className="flex flex-1 flex-col gap-4 p-4 pt-0 pb-20 md:pb-4">
          {children}
        </div>
      </SidebarInset>
      <PatientMobileNav />
    </SidebarProvider>
  );
}

import type { NavigationGroup } from "@/features/navigation/navigation.type";
import {
  BarChart3,
  Dumbbell,
  FileText,
  Heart,
  HeartHandshake,
  Home,
  MessageSquare,
  Pill,
  Settings,
  Users,
} from "lucide-react";

type Translator = (
  key: string,
  values?: Record<string, string | number>,
) => string;

export const getAppNavigation = (t: Translator): NavigationGroup[] => {
  return [
    {
      title: t("patient.nav.main"),
      defaultOpenStartPath: "/dashboard",
      links: [
        {
          href: "/dashboard",
          Icon: Home,
          label: t("nav.dashboard"),
        },
        {
          href: "/mood",
          Icon: Heart,
          label: t("patient.nav.mood"),
        },
        {
          href: "/trends",
          Icon: BarChart3,
          label: t("patient.nav.trends"),
        },
      ],
    },
    {
      title: t("patient.nav.tracking"),
      defaultOpenStartPath: "/medications",
      links: [
        {
          href: "/medications",
          Icon: Pill,
          label: t("patient.nav.medications"),
        },
        {
          href: "/exercises",
          Icon: Dumbbell,
          label: t("patient.nav.exercises"),
        },
        {
          href: "/therapy",
          Icon: MessageSquare,
          label: t("patient.nav.therapy"),
        },
        {
          href: "/caregiver",
          Icon: Users,
          label: t("patient.nav.caregiver"),
        },
      ],
    },
    {
      title: t("patient.nav.tools"),
      defaultOpenStartPath: "/export",
      links: [
        {
          href: "/crisis",
          Icon: HeartHandshake,
          label: t("patient.nav.crisis"),
        },
        {
          href: "/export",
          Icon: FileText,
          label: t("patient.nav.export"),
        },
        {
          href: "/settings",
          Icon: Settings,
          label: t("settings.title"),
        },
      ],
    },
  ];
};

