/**
 * Design Tokens for Moodday
 *
 * Centralized configuration for UI elements like mood colors,
 * context tags, side effects, sleep quality, etc.
 */

// ═══════════════════════════════════════════════════════════════
// MOOD COLORS (0-10 scale)
// ═══════════════════════════════════════════════════════════════

export const moodColors: Record<number, string> = {
  0: "#dc2626", // red-600
