    46→  const { t } = useI18n();
    47→
    48→  const chartData = useMemo(() => {
    49→    // Group entries by date and average if multiple per day
    50→    const byDate = new Map<
    51→      string,
    52→      { sum: number; count: number; notes: string[] }
    53→    >();
    54→
    55→    for (const entry of moodEntries) {
    56→      const dateKey = new Date(entry.date).toLocaleDateString("fr-FR", {
    57→        day: "2-digit",
    58→        month: "2-digit",
    59→      });
    60→
    61→      const existing = byDate.get(dateKey);
    62→      if (existing) {
    63→        existing.sum += entry.value;
    64→        existing.count += 1;
    65→        if (entry.note) existing.notes.push(entry.note);
    66→      } else {
    67→        byDate.set(dateKey, {
