     5→import Link from "next/link";
     6→import { useState } from "react";
     7→
     8→import { Badge } from "@/components/ui/badge";
     9→import { Button } from "@/components/ui/button";
    10→import { Card } from "@/components/ui/card";
    11→import { Skeleton } from "@/components/ui/skeleton";
    12→import { Switch } from "@/components/ui/switch";
    13→import { cn } from "@/lib/utils";
    14→import { getMedications } from "@/features/medication/medication.action";
    15→import { useI18n } from "@/i18n/provider";
    16→
    17→const FREQUENCY_LABELS: Record<string, string> = {
    18→  daily: "medication.frequency.daily",
    19→  twice_daily: "medication.frequency.twiceDaily",
    20→  weekly: "medication.frequency.weekly",
    21→  prn: "medication.frequency.prn",
    22→};
    23→
    24→export function MedicationList() {
    25→  const { t } = useI18n();
    26→  const [showArchived, setShowArchived] = useState(false);
    27→
    28→  const { data, isLoading, isError } = useQuery({
    29→    queryKey: ["medications", showArchived],
    30→    queryFn: async () => {
    31→      const result = await getMedications({ includeArchived: showArchived });
    32→      if (result.serverError) {
    33→        throw new Error(result.serverError);
    34→      }
    35→      return result.data;
    36→    },
    37→  });
    38→
    39→  const medications = data ?? [];
    40→  const activeMedications = medications.filter((m) => !m.isArchived);
    41→  const archivedMedications = medications.filter((m) => m.isArchived);
    42→
    43→  if (isError) {
    44→    return (
    45→      <Card className="p-8 text-center">
    46→        <p className="text-muted-foreground">{t("common.error")}</p>
    47→      </Card>
    48→    );
    49→  }
    50→
    51→  return (
    52→    <div className="space-y-6">
    53→      {/* Add button */}
    54→      <div className="flex justify-end">
    55→        <Button asChild>
    56→          <Link href="/medications/new">
    57→            <Plus className="mr-2 size-4" />
    58→            {t("medication.list.addNew")}
    59→          </Link>
    60→        </Button>
    61→      </div>
    62→
    63→      {/* Loading state */}
    64→      {isLoading && (
    65→        <div className="space-y-3">
    66→          {[...Array(3)].map((_, i) => (
    67→            <Skeleton key={i} className="h-24 w-full rounded-lg" />
    68→          ))}
    69→        </div>
    70→      )}
    71→
    72→      {/* Empty state */}
    73→      {!isLoading && activeMedications.length === 0 && !showArchived && (
    74→        <Card className="p-8 text-center">
    75→          <Pill className="text-muted-foreground mx-auto mb-4 size-12" />
    76→          <p className="text-muted-foreground">{t("medication.list.empty")}</p>
    77→        </Card>
    78→      )}
    79→
    80→      {/* Active medications */}
    81→      {activeMedications.length > 0 && (
    82→        <div className="space-y-3">
    83→          {activeMedications.map((medication) => (
    84→            <MedicationCard key={medication.id} medication={medication} />
    85→          ))}
    86→        </div>
    87→      )}
    88→
    89→      {/* Show archived toggle */}
    90→      {(archivedMedications.length > 0 || showArchived) && (
    91→        <div className="flex items-center justify-between border-t pt-4">
    92→          <span className="text-muted-foreground text-sm">
    93→            {showArchived
    94→              ? t("medication.list.hideArchived")
    95→              : t("medication.list.showArchived")}
    96→          </span>
    97→          <Switch checked={showArchived} onCheckedChange={setShowArchived} />
    98→        </div>
    99→      )}
   100→
