          padding="md"
          variant={selectedPeriod === "90" ? "elevated" : "default"}
          className={cn(
            "cursor-pointer transition-all",
            selectedPeriod === "90" && "ring-2 ring-[var(--primary)]/30",
          )}
          onClick={() => setSelectedPeriod("90")}
        >
