                    78%
                  </span>
                </div>
                <div className="mt-2 h-2 w-full overflow-hidden rounded-full bg-[var(--lavender)]/20">
                  <div
                    className="h-full rounded-full bg-[var(--lavender-dark)]"
                    style={{ width: "78%" }}
