              <GlassCardTitle
                icon={
                  <Sparkles className="size-5 text-[var(--lavender-dark)]" />
                }
              >
                IA Insights
              </GlassCardTitle>
            </GlassCardHeader>

            <GlassCardContent className="space-y-3">
              {insights && insights.length > 0 ? (
                insights.slice(0, 4).map((insight, index) => {
                  const style = insightTypeStyles[insight.type];
                  const IconComponent = style.icon;

                  return (
                    <div
                      key={index}
                      className={cn(
                        "flex items-start gap-3 rounded-2xl border p-4",
                        style.bg,
                        style.border,
                      )}
                    >
                      <IconComponent
                        className={cn(
                          "mt-0.5 size-5 shrink-0",
                          style.iconColor,
                        )}
                      />
                      <div>
                        <p className="text-sm leading-relaxed text-gray-700">
                          {insight.message}
                        </p>
                        {insight.trend !== "neutral" && (
                          <span
                            className={cn(
                              "mt-1 inline-flex items-center gap-1 text-xs font-bold",
                              insight.trend === "up"
                                ? "text-[var(--sage)]"
                                : "text-red-400",
                            )}
                          >
                            {insight.trend === "up" ? (
                              <TrendingUp className="size-3" />
                            ) : (
                              <TrendingDown className="size-3" />
                            )}
                            {insight.trend === "up" ? "En hausse" : "En baisse"}
                          </span>
                        )}
                      </div>
                    </div>
