    18→} from "@/components/ui/select";
    19→import { Skeleton } from "@/components/ui/skeleton";
    20→import {
    21→  getUserPreferences,
    22→  updateDisplayPreferences,
    23→  updateNotificationPreferences,
    24→} from "@/features/preferences/preferences.action";
    25→import { useI18n } from "@/i18n/provider";
    26→
    27→export function SettingsForm() {
    28→  const { t } = useI18n();
    29→  const queryClient = useQueryClient();
    30→
    31→  const { data: preferences, isLoading } = useQuery({
    32→    queryKey: ["user-preferences"],
    33→    queryFn: async () => {
    34→      const result = await getUserPreferences();
    35→      if (result.serverError) throw new Error(result.serverError);
    36→      return result.data;
    37→    },
    38→  });
    39→
    40→  const displayMutation = useMutation({
    41→    mutationFn: async (data: { defaultChartPeriod?: number }) => {
    42→      const result = await updateDisplayPreferences(data);
    43→      if (result.serverError) throw new Error(result.serverError);
    44→      return result.data;
    45→    },
    46→    onSuccess: () => {
    47→      toast.success(t("settings.saved"));
    48→      void queryClient.invalidateQueries({ queryKey: ["user-preferences"] });
    49→    },
    50→    onError: (error) => {
    51→      toast.error(error.message);
    52→    },
    53→  });
    54→
    55→  const notificationMutation = useMutation({
    56→    mutationFn: async (data: {
    57→      notificationsEnabled?: boolean;
    58→      dailyCheckInReminder?: boolean;
    59→      dailyCheckInTime?: string;
    60→      medicationReminders?: boolean;
    61→    }) => {
    62→      const result = await updateNotificationPreferences(data);
    63→      if (result.serverError) throw new Error(result.serverError);
    64→      return result.data;
    65→    },
    66→    onSuccess: () => {
    67→      toast.success(t("settings.saved"));
    68→      void queryClient.invalidateQueries({ queryKey: ["user-preferences"] });
    69→    },
    70→    onError: (error) => {
    71→      toast.error(error.message);
    72→    },
    73→  });
    74→
    75→  if (isLoading) {
    76→    return (
    77→      <div className="space-y-6">
    78→        <Skeleton className="h-48" />
    79→        <Skeleton className="h-64" />
    80→      </div>
    81→    );
    82→  }
    83→
    84→  return (
    85→    <div className="space-y-6">
    86→      {/* Display Settings */}
    87→      <Card>
    88→        <CardHeader>
    89→          <CardTitle>{t("settings.display.title")}</CardTitle>
    90→        </CardHeader>
    91→        <CardContent className="space-y-4">
    92→          <div className="space-y-2">
    93→            <Label>{t("settings.display.chartPeriod")}</Label>
    94→            <Select
    95→              value={String(preferences?.defaultChartPeriod ?? 30)}
    96→              onValueChange={(value) =>
    97→                displayMutation.mutate({ defaultChartPeriod: Number(value) })
    98→              }
    99→            >
   100→              <SelectTrigger>
   101→                <SelectValue />
   102→              </SelectTrigger>
   103→              <SelectContent>
   104→                <SelectItem value="7">{t("settings.display.days7")}</SelectItem>
   105→                <SelectItem value="30">
   106→                  {t("settings.display.days30")}
   107→                </SelectItem>
   108→                <SelectItem value="90">
   109→                  {t("settings.display.days90")}
   110→                </SelectItem>
   111→              </SelectContent>
   112→            </Select>
   113→            <p className="text-muted-foreground text-sm">
   114→              {t("settings.display.chartPeriodHint")}
   115→            </p>
   116→          </div>
   117→        </CardContent>
   118→      </Card>
   119→
   120→      {/* Notification Settings */}
   121→      <Card>
   122→        <CardHeader>
   123→          <CardTitle>{t("settings.notifications.title")}</CardTitle>
   124→        </CardHeader>
   125→        <CardContent className="space-y-6">
   126→          {/* Global toggle */}
   127→          <div className="flex items-center justify-between">
   128→            <div className="space-y-0.5">
   129→              <Label>{t("settings.notifications.enabled")}</Label>
   130→              <p className="text-muted-foreground text-sm">
   131→                {t("settings.notifications.enabledHint")}
   132→              </p>
   133→            </div>
   134→            <Switch
   135→              checked={preferences?.notificationsEnabled ?? true}
   136→              onCheckedChange={(checked) =>
   137→                notificationMutation.mutate({ notificationsEnabled: checked })
   138→              }
   139→            />
   140→          </div>
   141→
   142→          {preferences?.notificationsEnabled && (
   143→            <>
   144→              {/* Daily check-in */}
   145→              <div className="flex items-center justify-between">
   146→                <div className="space-y-0.5">
