                              notificationMutation.mutate({
                                medicationReminders: checked,
                              })
                            }
                          />
                        </div>
                      </>
                    )}
                  </GlassCardContent>
                </GlassCard>
              )}

              {/* Appearance Tab */}
              {activeTab === "appearance" && (
                <GlassCard padding="lg" variant="elevated">
                  <GlassCardHeader>
                    <GlassCardTitle
                      icon={<Palette className="size-5 text-[var(--primary)]" />}
                    >
