                    </GlassCardTitle>
                  </GlassCardHeader>

                  <GlassCardContent className="space-y-6">
                    <div className="space-y-4">
                      <Label className="text-gray-600">Thème</Label>
                      <div className="grid grid-cols-3 gap-4">
                        {[
                          {
                            id: "light",
                            icon: Sun,
                            label: "Clair",
                            bg: "bg-white",
                          },
                          {
                            id: "dark",
                            icon: Moon,
                            label: "Sombre",
                            bg: "bg-gray-900",
                          },
                          {
                            id: "zen",
                            icon: Sparkles,
                            label: "Zen",
                            bg: "bg-[var(--warm-bg)]",
                          },
                        ].map((theme) => {
