export function GlassCard({
  children,
  className,
  variant = "default",
  padding = "md",
  onClick,
}: GlassCardProps) {
  return (
    <div
      className={cn(
        "rounded-[32px]",
        variantClasses[variant],
        paddingClasses[padding],
        onClick && "cursor-pointer",
        className,
      )}
      onClick={onClick}
      role={onClick ? "button" : undefined}
      tabIndex={onClick ? 0 : undefined}
      onKeyDown={
        onClick
          ? (e) => {
              if (e.key === "Enter" || e.key === " ") {
                e.preventDefault();
                onClick();
              }
            }
          : undefined
      }
    >
      {children}
    </div>
  );
}

